CREATE OR REPLACE FUNCTION public.assign_referral_code_on_insert()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.referral_code IS NULL OR length(trim(NEW.referral_code)) = 0 THEN
    NEW.referral_code := public.generate_referral_code();
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.award_badge(_user_id uuid, _badge_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_id uuid;
  v_points int;
  v_required int;
  v_user_points int;
BEGIN
  -- Verify badge exists and user meets points requirement
  SELECT points_required INTO v_required FROM public.badges WHERE id = _badge_id AND is_active = true;
  IF v_required IS NULL THEN
    RAISE EXCEPTION 'Badge not found or inactive';
  END IF;

  SELECT total_points INTO v_user_points FROM public.profiles WHERE id = _user_id;
  IF COALESCE(v_user_points, 0) < v_required THEN
    RAISE EXCEPTION 'User does not meet points requirement';
  END IF;

  INSERT INTO public.user_badges (user_id, badge_id)
  VALUES (_user_id, _badge_id)
  ON CONFLICT DO NOTHING
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.award_mission_points(p_mission_id uuid, p_block_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_blocks jsonb;
  v_block jsonb;
  v_points int := 0;
  v_ref text := p_mission_id::text || ':' || p_block_id;
  v_total int;
BEGIN
  IF v_uid IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'unauthenticated'); END IF;

  SELECT blocks INTO v_blocks FROM public.daily_missions
  WHERE id = p_mission_id AND user_id = v_uid;
  IF v_blocks IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'mission_not_found'); END IF;

  SELECT b INTO v_block FROM jsonb_array_elements(v_blocks) b
  WHERE b->>'id' = p_block_id LIMIT 1;
  IF v_block IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'block_not_found'); END IF;

  IF COALESCE(v_block->'progress'->>'status', 'pending') <> 'done' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'block_not_done');
  END IF;

  IF EXISTS (SELECT 1 FROM public.points_log WHERE user_id = v_uid AND reference_id = v_ref) THEN
    RETURN jsonb_build_object('ok', true, 'points', 0, 'already_claimed', true);
  END IF;

  v_points := GREATEST(0, LEAST(500, COALESCE((v_block->>'xp_reward')::int, 20)));

  INSERT INTO public.points_log (user_id, action_type, points, description, reference_id)
  VALUES (v_uid, 'mission_block', v_points, COALESCE(v_block->>'title', 'Challenge complete'), v_ref);

  UPDATE public.profiles
  SET total_points = COALESCE(total_points, 0) + v_points
  WHERE id = v_uid
  RETURNING total_points INTO v_total;

  RETURN jsonb_build_object('ok', true, 'points', v_points, 'total_points', v_total);
END;
$function$

CREATE OR REPLACE FUNCTION public.award_xp(p_is_correct boolean, p_combo integer DEFAULT 0, p_amount integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_today date := (now() AT TIME ZONE 'Asia/Kolkata')::date;
  v_xp integer := 0;
  v_daily integer := 0;
  v_goal integer := 15;
  v_streak integer := 0;
  v_league uuid;
BEGIN
  IF v_uid IS NULL THEN RETURN jsonb_build_object('error','Unauthorized'); END IF;

  IF p_amount IS NOT NULL THEN
    v_xp := GREATEST(p_amount, 0);
  ELSIF p_is_correct THEN
    v_xp := 10
      + CASE WHEN p_combo >= 10 THEN 20
             WHEN p_combo >= 5 THEN 10
             WHEN p_combo >= 3 THEN 5
             ELSE 0 END;
  ELSE
    v_xp := 0;
  END IF;

  UPDATE public.profiles
  SET daily_xp = CASE WHEN daily_xp_date IS DISTINCT FROM v_today THEN v_xp ELSE COALESCE(daily_xp,0) + v_xp END,
      daily_xp_date = v_today,
      updated_at = now()
  WHERE id = v_uid
  RETURNING daily_xp, COALESCE(daily_goal,15), COALESCE(current_streak,0)
  INTO v_daily, v_goal, v_streak;

  IF v_xp > 0 THEN
    v_league := public.join_current_league();
    IF v_league IS NOT NULL THEN
      UPDATE public.league_members
      SET xp = xp + v_xp, updated_at = now()
      WHERE league_id = v_league AND user_id = v_uid;
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'xp_awarded', v_xp,
    'daily_xp', COALESCE(v_daily,0),
    'xp_goal', GREATEST(v_goal,1) * 10,
    'streak', v_streak
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.backfill_text_quality(p_limit integer DEFAULT 5000)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE n integer;
BEGIN
  WITH batch AS (
    SELECT id FROM public.questions WHERE text_quality IS NULL LIMIT GREATEST(p_limit,1)
  )
  UPDATE public.questions q
    SET text_quality = public.classify_question_text(q.question_text)
  FROM batch b WHERE q.id = b.id;
  GET DIAGNOSTICS n = ROW_COUNT;
  RETURN n;
END;
$function$

CREATE OR REPLACE FUNCTION public.bump_mission_block_progress(p_mission_id uuid, p_block_id text, p_is_correct boolean, p_question_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  m RECORD;
  new_blocks jsonb;
  block_obj jsonb;
  block_idx INT := -1;
  i INT;
  target INT;
  passing_goal INT;
  attempted INT;
  correct_count INT;
  seen_ids jsonb;
  block_status TEXT;
  is_now_done BOOLEAN := FALSE;
  new_completed INT;
  new_status TEXT;
  xp_reward INT := 0;
  xp_awarded INT := 0;
  bonus_awarded INT := 0;
  today_ist DATE := (now() AT TIME ZONE 'Asia/Kolkata')::date;
BEGIN
  SELECT * INTO m FROM public.daily_missions WHERE id = p_mission_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'error', 'mission_not_found'); END IF;
  IF m.user_id <> auth.uid() THEN RETURN jsonb_build_object('ok', false, 'error', 'forbidden'); END IF;

  new_blocks := m.blocks;
  FOR i IN 0 .. jsonb_array_length(new_blocks) - 1 LOOP
    IF (new_blocks -> i ->> 'id') = p_block_id THEN
      block_idx := i;
      EXIT;
    END IF;
  END LOOP;
  IF block_idx < 0 THEN RETURN jsonb_build_object('ok', false, 'error', 'block_not_found'); END IF;

  block_obj := new_blocks -> block_idx;
  target := COALESCE((block_obj ->> 'question_count')::INT, 10);
  passing_goal := COALESCE((block_obj ->> 'passing_goal')::INT, GREATEST(1, (target * 0.6)::INT));
  attempted := COALESCE((block_obj -> 'progress' ->> 'attempted')::INT, 0);
  correct_count := COALESCE((block_obj -> 'progress' ->> 'correct')::INT, 0);
  seen_ids := COALESCE(block_obj -> 'progress' -> 'seen_ids', '[]'::jsonb);
  block_status := COALESCE(block_obj -> 'progress' ->> 'status', 'pending');
  xp_reward := COALESCE((block_obj ->> 'xp_reward')::INT, target * 10);

  IF seen_ids @> to_jsonb(p_question_id::TEXT) THEN
    RETURN jsonb_build_object('ok', true, 'skipped', true, 'block', block_obj);
  END IF;

  attempted := attempted + 1;
  IF p_is_correct THEN correct_count := correct_count + 1; END IF;
  seen_ids := seen_ids || to_jsonb(p_question_id::TEXT);

  IF block_status <> 'done' AND (attempted >= target OR correct_count >= passing_goal) THEN
    block_status := 'done';
    is_now_done := TRUE;
  ELSIF block_status = 'pending' THEN
    block_status := 'in_progress';
  END IF;

  block_obj := jsonb_set(block_obj, '{progress}', jsonb_build_object(
    'attempted', attempted,
    'correct', correct_count,
    'status', block_status,
    'seen_ids', seen_ids
  ));
  new_blocks := jsonb_set(new_blocks, ARRAY[block_idx::TEXT], block_obj);

  new_completed := 0;
  FOR i IN 0 .. jsonb_array_length(new_blocks) - 1 LOOP
    IF (new_blocks -> i -> 'progress' ->> 'status') = 'done' THEN
      new_completed := new_completed + 1;
    END IF;
  END LOOP;

  new_status := m.status;
  IF new_completed >= jsonb_array_length(new_blocks) THEN
    new_status := 'completed';
  ELSIF new_status = 'pending' THEN
    new_status := 'in_progress';
  END IF;

  -- XP: award on block completion + bonus on full mission
  IF is_now_done THEN
    xp_awarded := xp_reward;
  END IF;
  IF is_now_done AND new_status = 'completed' AND m.status <> 'completed' THEN
    bonus_awarded := 100;
  END IF;

  IF (xp_awarded + bonus_awarded) > 0 THEN
    UPDATE public.profiles
    SET total_points = COALESCE(total_points, 0) + xp_awarded + bonus_awarded,
        daily_xp = CASE WHEN daily_xp_date = today_ist
                        THEN COALESCE(daily_xp, 0) + xp_awarded + bonus_awarded
                        ELSE xp_awarded + bonus_awarded END,
        daily_xp_date = today_ist,
        updated_at = now()
    WHERE id = m.user_id;
  END IF;

  UPDATE public.daily_missions
  SET blocks = new_blocks,
      completed_blocks = new_completed,
      status = new_status,
      started_at = COALESCE(started_at, now()),
      completed_at = CASE WHEN new_status = 'completed' THEN now() ELSE completed_at END,
      updated_at = now()
  WHERE id = p_mission_id;

  RETURN jsonb_build_object(
    'ok', true,
    'block', block_obj,
    'block_done', is_now_done,
    'completed_blocks', new_completed,
    'mission_status', new_status,
    'xp_awarded', xp_awarded,
    'bonus_awarded', bonus_awarded
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.bump_mission_progress_by_chapter(p_chapter_id uuid, p_is_correct boolean, p_question_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  m RECORD;
  matched_block_id TEXT;
  today_ist DATE;
BEGIN
  today_ist := (now() AT TIME ZONE 'Asia/Kolkata')::date;

  SELECT * INTO m
  FROM public.daily_missions
  WHERE user_id = auth.uid()
    AND mission_date = today_ist
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'no_mission_today');
  END IF;

  -- Find first non-done block matching this chapter
  FOR i IN 0 .. jsonb_array_length(m.blocks) - 1 LOOP
    IF (m.blocks -> i ->> 'chapter_id') = p_chapter_id::TEXT
       AND COALESCE(m.blocks -> i -> 'progress' ->> 'status', 'pending') <> 'done' THEN
      matched_block_id := m.blocks -> i ->> 'id';
      EXIT;
    END IF;
  END LOOP;

  IF matched_block_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'no_matching_block');
  END IF;

  RETURN public.bump_mission_block_progress(m.id, matched_block_id, p_is_correct, p_question_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.change_user_goal(p_user_id uuid, p_new_goal text, p_new_grade integer, p_new_target_exam text, p_confirm_reset boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_old_exam TEXT;
  v_old_grade INTEGER;
  v_reset_result JSONB;
BEGIN
  SELECT target_exam, grade INTO v_old_exam, v_old_grade FROM profiles WHERE id = p_user_id;

  IF v_old_exam = p_new_target_exam AND v_old_grade = p_new_grade THEN
    RETURN jsonb_build_object('success', false, 'reason', 'Same goal selected');
  END IF;

  IF NOT p_confirm_reset THEN
    RETURN jsonb_build_object('success', false, 'requires_confirmation', true, 'warning', 'Changing your goal will reset all progress.', 'old_exam', v_old_exam, 'new_exam', p_new_target_exam);
  END IF;

  v_reset_result := public.reset_user_progress(p_user_id);

  UPDATE profiles SET
    grade = p_new_grade, target_exam = p_new_target_exam,
    goal_locked = false, goal_locked_at = NULL, updated_at = now()
  WHERE id = p_user_id;

  RETURN jsonb_build_object('success', true, 'old_exam', v_old_exam, 'new_exam', p_new_target_exam, 'data_reset', v_reset_result);
END;
$function$

CREATE OR REPLACE FUNCTION public.chapters_legacy_sync()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_subject_id uuid;
BEGIN
  -- Sync name <-> chapter_name (whichever is provided)
  IF NEW.name IS NULL AND NEW.chapter_name IS NOT NULL THEN
    NEW.name := NEW.chapter_name;
  ELSIF NEW.chapter_name IS NULL AND NEW.name IS NOT NULL THEN
    NEW.chapter_name := NEW.name;
  END IF;

  -- Resolve subject_id from subject text if missing
  IF NEW.subject_id IS NULL AND NEW.subject IS NOT NULL THEN
    SELECT id INTO v_subject_id
    FROM public.subjects
    WHERE LOWER(name) = LOWER(NEW.subject)
    LIMIT 1;
    IF v_subject_id IS NOT NULL THEN
      NEW.subject_id := v_subject_id;
    END IF;
  END IF;

  -- Resolve subject text from subject_id if missing
  IF NEW.subject IS NULL AND NEW.subject_id IS NOT NULL THEN
    SELECT name INTO NEW.subject FROM public.subjects WHERE id = NEW.subject_id;
  END IF;

  -- Generate slug if missing
  IF NEW.slug IS NULL OR NEW.slug = '' THEN
    NEW.slug := lower(regexp_replace(COALESCE(NEW.name, NEW.chapter_name, 'chapter'), '[^a-zA-Z0-9]+', '-', 'g'));
  END IF;

  -- Default class_level if missing
  IF NEW.class_level IS NULL THEN
    NEW.class_level := 11;
  END IF;

  -- Default exam_relevance if missing
  IF NEW.exam_relevance IS NULL OR array_length(NEW.exam_relevance, 1) IS NULL THEN
    NEW.exam_relevance := ARRAY['JEE_MAINS']::exam_code[];
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.chapters_propagate_class_level()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.class_level IS DISTINCT FROM OLD.class_level THEN
    UPDATE public.questions SET class_level = NEW.class_level WHERE chapter_id = NEW.id;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.check_and_award_badges(_user_id uuid)
 RETURNS TABLE(badge_id uuid, code text, name text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_streak INT := 0;
  v_total_q INT := 0;
  v_total_correct INT := 0;
  v_best_correct_streak INT := 0;
  v_max_daily INT := 0;
  v_perfect_tests INT := 0;
  v_morning INT := 0;
  v_night INT := 0;
  v_shares INT := 0;
  v_badge RECORD;
  v_qualifies BOOLEAN;
BEGIN
  -- Pull user snapshot
  SELECT COALESCE(current_streak, 0) INTO v_streak FROM public.profiles WHERE id = _user_id;

  SELECT COUNT(*), COUNT(*) FILTER (WHERE is_correct)
    INTO v_total_q, v_total_correct
    FROM public.question_attempts WHERE user_id = _user_id;

  -- Longest consecutive correct-answer streak (window walk)
  WITH ordered AS (
    SELECT is_correct,
           ROW_NUMBER() OVER (ORDER BY attempted_at) -
           ROW_NUMBER() OVER (PARTITION BY is_correct ORDER BY attempted_at) AS grp
    FROM public.question_attempts WHERE user_id = _user_id
  )
  SELECT COALESCE(MAX(cnt), 0) INTO v_best_correct_streak
  FROM (SELECT COUNT(*) AS cnt FROM ordered WHERE is_correct GROUP BY grp) s;

  -- Max questions in a single day
  SELECT COALESCE(MAX(cnt), 0) INTO v_max_daily
  FROM (
    SELECT COUNT(*) AS cnt
    FROM public.question_attempts
    WHERE user_id = _user_id
    GROUP BY date_trunc('day', attempted_at)
  ) d;

  -- Perfect test count
  SELECT COUNT(*) INTO v_perfect_tests
  FROM public.test_sessions
  WHERE user_id = _user_id AND score = 100 AND total_questions >= 5;

  -- Morning sessions (before 8am local UTC approx) — count distinct days
  SELECT COUNT(DISTINCT date_trunc('day', attempted_at)) INTO v_morning
  FROM public.question_attempts
  WHERE user_id = _user_id AND EXTRACT(HOUR FROM attempted_at) < 8;

  SELECT COUNT(DISTINCT date_trunc('day', attempted_at)) INTO v_night
  FROM public.question_attempts
  WHERE user_id = _user_id AND EXTRACT(HOUR FROM attempted_at) >= 23;

  -- Shares from points_log
  SELECT COUNT(*) INTO v_shares
  FROM public.points_log
  WHERE user_id = _user_id AND action_type IN ('badge_share', 'result_share', 'share');

  -- Iterate badges and award missing
  FOR v_badge IN
    SELECT b.id, b.code, b.name, b.requirement_type, b.requirement_value
    FROM public.badges b
    WHERE b.is_active = true
      AND NOT EXISTS (
        SELECT 1 FROM public.user_badges ub
        WHERE ub.user_id = _user_id AND ub.badge_id = b.id
      )
  LOOP
    v_qualifies := CASE v_badge.requirement_type
      WHEN 'day_streak'       THEN v_streak            >= v_badge.requirement_value
      WHEN 'answer_streak'    THEN v_best_correct_streak >= v_badge.requirement_value
      WHEN 'total_questions'  THEN v_total_q           >= v_badge.requirement_value
      WHEN 'total_correct'    THEN v_total_correct     >= v_badge.requirement_value
      WHEN 'daily_questions'  THEN v_max_daily         >= v_badge.requirement_value
      WHEN 'perfect_test'     THEN v_perfect_tests     >= v_badge.requirement_value
      WHEN 'morning_sessions' THEN v_morning           >= v_badge.requirement_value
      WHEN 'night_sessions'   THEN v_night             >= v_badge.requirement_value
      WHEN 'shares'           THEN v_shares            >= v_badge.requirement_value
      ELSE FALSE
    END;

    IF v_qualifies THEN
      INSERT INTO public.user_badges (user_id, badge_id, earned_at)
      VALUES (_user_id, v_badge.id, now())
      ON CONFLICT DO NOTHING;
      badge_id := v_badge.id; code := v_badge.code; name := v_badge.name;
      RETURN NEXT;
    END IF;
  END LOOP;
END $function$

CREATE OR REPLACE FUNCTION public.check_and_reset_streak(p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_profile RECORD;
  v_today text;
  v_yesterday text;
  v_days_since integer;
BEGIN
  IF auth.uid() IS NULL OR auth.uid() != p_user_id THEN
    RETURN jsonb_build_object('error', 'Unauthorized');
  END IF;

  v_today := to_char(now() AT TIME ZONE 'Asia/Kolkata', 'YYYY-MM-DD');
  v_yesterday := to_char((now() AT TIME ZONE 'Asia/Kolkata' - interval '1 day'), 'YYYY-MM-DD');

  SELECT current_streak, last_activity_date, last_streak_date, streak_freeze_available
  INTO v_profile FROM public.profiles WHERE id = p_user_id;

  IF NOT FOUND OR v_profile.last_activity_date IS NULL THEN
    RETURN jsonb_build_object('success', true, 'streak', 0, 'reset', false);
  END IF;

  IF v_profile.last_streak_date IS NOT NULL AND
     (v_profile.last_streak_date::text = v_today OR v_profile.last_streak_date::text = v_yesterday) THEN
    RETURN jsonb_build_object('success', true, 'streak', COALESCE(v_profile.current_streak, 0), 'reset', false);
  END IF;

  IF v_profile.last_streak_date IS NOT NULL THEN
    v_days_since := (v_today::date - v_profile.last_streak_date)::integer;
  ELSE
    v_days_since := 999;
  END IF;

  IF v_days_since = 2 AND COALESCE(v_profile.streak_freeze_available, false) THEN
    RETURN jsonb_build_object('success', true, 'streak', COALESCE(v_profile.current_streak, 0), 'reset', false, 'freeze_available', true);
  END IF;

  IF COALESCE(v_profile.current_streak, 0) > 0 THEN
    UPDATE public.profiles
    SET current_streak = 0,
        pending_streak_repair = v_profile.current_streak,
        pending_streak_repair_date = (now() AT TIME ZONE 'Asia/Kolkata')::date,
        updated_at = now()
    WHERE id = p_user_id;
    RETURN jsonb_build_object('success', true, 'streak', 0, 'reset', true, 'previous_streak', v_profile.current_streak, 'repair_available', true);
  END IF;

  RETURN jsonb_build_object('success', true, 'streak', 0, 'reset', false);
END;
$function$

CREATE OR REPLACE FUNCTION public.claim_daily_vault()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_today date := (now() AT TIME ZONE 'Asia/Kolkata')::date;
  v_blocks jsonb;
  v_done int;
  v_total int;
  v_roll numeric;
  v_rarity text;
  v_type text;
  v_points int;
  v_payload jsonb;
  v_new_total int;
BEGIN
  IF v_uid IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'unauthenticated'); END IF;

  IF EXISTS (SELECT 1 FROM public.reward_vault_claims WHERE user_id = v_uid AND claim_date = v_today) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'already_claimed');
  END IF;

  SELECT blocks INTO v_blocks FROM public.daily_missions
  WHERE user_id = v_uid AND mission_date = v_today;
  IF v_blocks IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'chain_incomplete'); END IF;

  SELECT count(*) FILTER (WHERE COALESCE(b->'progress'->>'status','pending') = 'done'), count(*)
  INTO v_done, v_total FROM jsonb_array_elements(v_blocks) b;

  IF v_total = 0 OR v_done < v_total THEN
    RETURN jsonb_build_object('ok', false, 'error', 'chain_incomplete');
  END IF;

  v_roll := random();
  IF v_roll < 0.55 THEN
    v_rarity := 'common'; v_type := 'points'; v_points := 25 + floor(random()*26)::int;
    v_payload := jsonb_build_object('label', '+' || v_points || ' JEEnie Points');
  ELSIF v_roll < 0.83 THEN
    v_rarity := 'rare'; v_type := 'points'; v_points := 75 + floor(random()*51)::int;
    v_payload := jsonb_build_object('label', '+' || v_points || ' JEEnie Points');
  ELSIF v_roll < 0.96 THEN
    v_rarity := 'epic'; v_type := 'streak_freeze'; v_points := 50;
    v_payload := jsonb_build_object('label', 'Streak Freeze', 'code', 'streak_freeze');
  ELSE
    v_rarity := 'legendary'; v_type := 'title'; v_points := 150;
    v_payload := jsonb_build_object('label', 'Title: Chain Breaker', 'code', 'chain_breaker');
  END IF;

  INSERT INTO public.reward_vault_claims (user_id, claim_date, reward_type, rarity, points_awarded, payload)
  VALUES (v_uid, v_today, v_type, v_rarity, v_points, v_payload);

  IF v_type <> 'points' THEN
    INSERT INTO public.user_inventory (user_id, item_type, item_code, label, quantity)
    VALUES (v_uid, v_type, v_payload->>'code', v_payload->>'label', 1)
    ON CONFLICT DO NOTHING;
  END IF;

  INSERT INTO public.points_log (user_id, action_type, points, description, reference_id)
  VALUES (v_uid, 'daily_vault', v_points, 'Daily Vault (' || v_rarity || ')', 'vault:' || v_today::text);

  UPDATE public.profiles SET total_points = COALESCE(total_points,0) + v_points
  WHERE id = v_uid RETURNING total_points INTO v_new_total;

  RETURN jsonb_build_object('ok', true, 'rarity', v_rarity, 'reward_type', v_type,
    'points', v_points, 'payload', v_payload, 'total_points', v_new_total);
END;
$function$

CREATE OR REPLACE FUNCTION public.community_accept_reply(p_reply_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_post community_posts%ROWTYPE; v_reply community_replies%ROWTYPE; v_points integer := 25;
BEGIN
  SELECT * INTO v_reply FROM community_replies WHERE id = p_reply_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('error','reply_not_found'); END IF;
  SELECT * INTO v_post FROM community_posts WHERE id = v_reply.post_id;
  IF v_post.user_id <> auth.uid() THEN RETURN jsonb_build_object('error','not_owner'); END IF;
  UPDATE community_replies SET is_accepted = false WHERE post_id = v_post.id;
  UPDATE community_replies SET is_accepted = true WHERE id = p_reply_id;
  UPDATE community_posts SET is_solved = true, accepted_reply_id = p_reply_id, updated_at = now() WHERE id = v_post.id;
  IF NOT v_reply.points_awarded AND v_reply.user_id <> v_post.user_id THEN
    UPDATE community_replies SET points_awarded = true WHERE id = p_reply_id;
    UPDATE profiles SET total_points = COALESCE(total_points,0) + v_points WHERE id = v_reply.user_id;
    INSERT INTO points_log (user_id, action_type, points, description, reference_id)
    VALUES (v_reply.user_id, 'community_accepted_answer', v_points, 'Answer accepted in community', p_reply_id::text);
  END IF;
  RETURN jsonb_build_object('ok', true, 'points', v_points);
END; $function$

CREATE OR REPLACE FUNCTION public.community_toggle_vote(p_post_id uuid, p_reply_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_existing uuid; v_count integer;
BEGIN
  IF auth.uid() IS NULL THEN RETURN jsonb_build_object('error','not_authenticated'); END IF;
  IF p_post_id IS NOT NULL THEN
    SELECT id INTO v_existing FROM community_votes WHERE user_id = auth.uid() AND post_id = p_post_id;
    IF v_existing IS NOT NULL THEN DELETE FROM community_votes WHERE id = v_existing;
    ELSE INSERT INTO community_votes (user_id, post_id) VALUES (auth.uid(), p_post_id); END IF;
    SELECT count(*) INTO v_count FROM community_votes WHERE post_id = p_post_id;
    UPDATE community_posts SET upvotes = v_count WHERE id = p_post_id;
    RETURN jsonb_build_object('upvotes', v_count, 'voted', v_existing IS NULL);
  ELSIF p_reply_id IS NOT NULL THEN
    SELECT id INTO v_existing FROM community_votes WHERE user_id = auth.uid() AND reply_id = p_reply_id;
    IF v_existing IS NOT NULL THEN DELETE FROM community_votes WHERE id = v_existing;
    ELSE INSERT INTO community_votes (user_id, reply_id) VALUES (auth.uid(), p_reply_id); END IF;
    SELECT count(*) INTO v_count FROM community_votes WHERE reply_id = p_reply_id;
    UPDATE community_replies SET upvotes = v_count WHERE id = p_reply_id;
    RETURN jsonb_build_object('upvotes', v_count, 'voted', v_existing IS NULL);
  END IF;
  RETURN jsonb_build_object('error','no_target');
END; $function$

CREATE OR REPLACE FUNCTION public.count_unseen_questions(p_user_id uuid, p_exam text DEFAULT NULL::text, p_subject text DEFAULT NULL::text, p_chapter_id uuid DEFAULT NULL::uuid, p_topic_id uuid DEFAULT NULL::uuid)
 RETURNS integer
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_subject text;
  v_grade integer;
  v_pool text[];
  v_scope text;
  v_count integer;
BEGIN
  v_subject := COALESCE(
    p_subject,
    (SELECT c.subject FROM public.chapters c WHERE c.id = p_chapter_id),
    (SELECT c2.subject FROM public.topics t JOIN public.chapters c2 ON c2.id = t.chapter_id WHERE t.id = p_topic_id)
  );
  SELECT pr.grade INTO v_grade FROM public.profiles pr WHERE pr.id = p_user_id;
  v_pool := public.exam_pool(p_exam, v_subject);

  IF p_topic_id IS NOT NULL THEN v_scope := 'topic';
  ELSIF p_chapter_id IS NOT NULL THEN v_scope := 'chapter';
  ELSIF p_subject IS NOT NULL THEN v_scope := 'subject';
  ELSE v_scope := 'all';
  END IF;

  SELECT count(*) INTO v_count FROM (
    SELECT 1
    FROM public.questions q
    WHERE (q.is_active IS NULL OR q.is_active = true)
      AND (q.text_quality IS NULL OR q.text_quality <> 'damaged')
      AND (v_scope <> 'topic'   OR q.topic_id = p_topic_id)
      AND (v_scope <> 'chapter' OR q.chapter_id = p_chapter_id)
      AND (v_scope <> 'subject' OR lower(q.subject) = lower(p_subject))
      AND (v_pool IS NULL OR q.exam = ANY(v_pool))
      AND (v_scope IN ('topic','chapter') OR v_grade IS NULL OR q.class_level IS NULL OR q.class_level = v_grade)
      AND NOT EXISTS (
        SELECT 1 FROM public.question_attempts qa
        WHERE qa.user_id = p_user_id AND qa.question_id = q.id
      )
    LIMIT 500
  ) s;

  RETURN COALESCE(v_count, 0);
END;
$function$

CREATE OR REPLACE FUNCTION public.create_referral(p_referral_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_referrer_id uuid;
  v_user_id uuid;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('error', 'Not authenticated');
  END IF;

  -- Find the actual owner of the referral code
  SELECT id INTO v_referrer_id FROM profiles WHERE referral_code = p_referral_code;
  IF v_referrer_id IS NULL THEN
    RETURN jsonb_build_object('error', 'Invalid referral code');
  END IF;

  -- Can't refer yourself
  IF v_referrer_id = v_user_id THEN
    RETURN jsonb_build_object('error', 'Cannot refer yourself');
  END IF;

  -- Check if already referred
  IF EXISTS (SELECT 1 FROM referrals WHERE referred_id = v_user_id) THEN
    RETURN jsonb_build_object('error', 'Already used a referral');
  END IF;

  INSERT INTO referrals (referrer_id, referred_id, referral_code, status)
  VALUES (v_referrer_id, v_user_id, p_referral_code, 'completed');

  RETURN jsonb_build_object('success', true, 'referrer_id', v_referrer_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.delete_duplicate_questions()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_total   bigint := 0;
  v_deleted bigint := 0;
BEGIN
  SELECT COUNT(*) INTO v_total FROM questions;

  WITH ranked AS (
    SELECT
      id,
      ROW_NUMBER() OVER (
        PARTITION BY LEFT(LOWER(TRIM(REGEXP_REPLACE(question, '\s+', ' ', 'g'))), 100)
        ORDER BY created_at ASC NULLS LAST, id ASC
      ) AS rn
    FROM questions
  )
  DELETE FROM questions
  WHERE id IN (SELECT id FROM ranked WHERE rn > 1);

  GET DIAGNOSTICS v_deleted = ROW_COUNT;

  RETURN jsonb_build_object(
    'success',          true,
    'total_scanned',    v_total,
    'deleted',          v_deleted,
    'unique_questions', v_total - v_deleted
  );
END;
$function$

