CREATE OR REPLACE FUNCTION public.fetch_unseen_questions(p_user_id uuid, p_exam text DEFAULT NULL::text, p_subject text DEFAULT NULL::text, p_chapter_id uuid DEFAULT NULL::uuid, p_topic_id uuid DEFAULT NULL::uuid, p_topic_name text DEFAULT NULL::text, p_batch_ids uuid[] DEFAULT NULL::uuid[], p_limit integer DEFAULT 100)
 RETURNS SETOF questions
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_subject text;
  v_grade integer;
  v_native text[];
  v_pool text[];
  v_scope text;
BEGIN
  v_subject := COALESCE(
    p_subject,
    (SELECT c.subject FROM public.chapters c WHERE c.id = p_chapter_id),
    (SELECT c2.subject FROM public.topics t JOIN public.chapters c2 ON c2.id = t.chapter_id WHERE t.id = p_topic_id)
  );
  SELECT pr.grade INTO v_grade FROM public.profiles pr WHERE pr.id = p_user_id;
  v_native := public.exam_family(p_exam);
  v_pool := public.exam_pool(p_exam, v_subject);

  IF p_topic_id IS NOT NULL THEN v_scope := 'topic';
  ELSIF p_chapter_id IS NOT NULL THEN v_scope := 'chapter';
  ELSIF p_subject IS NOT NULL THEN v_scope := 'subject';
  ELSE v_scope := 'all';
  END IF;

  RETURN QUERY
  WITH candidates AS (
    SELECT q.id, q.exam
    FROM public.questions q
    WHERE (q.is_active IS NULL OR q.is_active = true)
      AND (q.text_quality IS NULL OR q.text_quality <> 'damaged')
      AND (v_scope <> 'topic'   OR q.topic_id = p_topic_id)
      AND (v_scope <> 'chapter' OR q.chapter_id = p_chapter_id)
      AND (v_scope <> 'subject' OR lower(q.subject) = lower(p_subject))
      AND (v_pool IS NULL OR q.exam = ANY(v_pool))
      AND (
        v_scope IN ('topic','chapter')
        OR v_grade IS NULL
        OR q.class_level IS NULL
        OR q.class_level = v_grade
      )
      AND (p_topic_name IS NULL OR q.topic ILIKE '%' || p_topic_name || '%')
      AND (p_batch_ids IS NULL OR array_length(p_batch_ids, 1) IS NULL OR q.batch_id = ANY(p_batch_ids))
      AND NOT EXISTS (
        SELECT 1 FROM public.question_attempts qa
        WHERE qa.user_id = p_user_id AND qa.question_id = q.id
      )
    LIMIT 4000
  ),
  picked AS (
    SELECT c.id FROM candidates c
    ORDER BY
      (CASE WHEN v_native IS NULL OR c.exam = ANY(v_native) THEN 0 ELSE 1 END),
      random()
    LIMIT GREATEST(p_limit, 1)
  )
  SELECT q.* FROM public.questions q JOIN picked p ON p.id = q.id;
END;
$function$

CREATE OR REPLACE FUNCTION public.finish_battle(p_battle_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user uuid := auth.uid();
  v_winner uuid;
  v_player record;
  v_reward_points integer;
BEGIN
  IF v_user IS NULL THEN
    RETURN jsonb_build_object('error', 'not_authenticated');
  END IF;

  IF NOT EXISTS (SELECT 1 FROM public.battle_players WHERE battle_id = p_battle_id AND user_id = v_user) THEN
    RETURN jsonb_build_object('error', 'not_in_battle');
  END IF;

  UPDATE public.battle_players
  SET finished_at = COALESCE(finished_at, now())
  WHERE battle_id = p_battle_id AND user_id = v_user;

  SELECT user_id INTO v_winner
  FROM public.battle_players
  WHERE battle_id = p_battle_id
  ORDER BY score DESC, correct_count DESC, joined_at ASC
  LIMIT 1;

  IF NOT EXISTS (
    SELECT 1
    FROM public.battle_players bp
    WHERE bp.battle_id = p_battle_id AND bp.finished_at IS NULL
  ) OR EXISTS (
    SELECT 1 FROM public.battle_sessions bs WHERE bs.id = p_battle_id AND bs.expires_at <= now()
  ) THEN
    UPDATE public.battle_sessions
    SET status = 'completed', completed_at = COALESCE(completed_at, now()), winner_user_id = v_winner, updated_at = now()
    WHERE id = p_battle_id;

    FOR v_player IN SELECT * FROM public.battle_players WHERE battle_id = p_battle_id LOOP
      v_reward_points := CASE WHEN v_player.user_id = v_winner THEN 250 ELSE 75 END;
      INSERT INTO public.battle_rewards (battle_id, user_id, points, title)
      VALUES (p_battle_id, v_player.user_id, v_reward_points, CASE WHEN v_player.user_id = v_winner THEN 'Battle Champion' ELSE 'Battle Finisher' END)
      ON CONFLICT (battle_id, user_id, reward_type) DO NOTHING;

      UPDATE public.profiles
      SET total_points = COALESCE(total_points, 0) + v_reward_points,
          updated_at = now()
      WHERE id = v_player.user_id;

      INSERT INTO public.points_log (user_id, action_type, points, description, reference_id)
      VALUES (v_player.user_id, 'battle_reward', v_reward_points, CASE WHEN v_player.user_id = v_winner THEN 'Won a Pro+ battle' ELSE 'Completed a Pro+ battle' END, p_battle_id::text);
    END LOOP;
  END IF;

  RETURN jsonb_build_object('battle_id', p_battle_id, 'winner_user_id', v_winner);
END;
$function$

CREATE OR REPLACE FUNCTION public.fix_chapter_batch_distribution()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_moved int := 0;
  v_chapter record;
  v_correct_grade int;
  v_current_batch record;
  v_target_batch record;
  v_target_chapter_id uuid;
  v_moved_count int;
  v_moves jsonb := '[]'::jsonb;
BEGIN
  -- Process each chapter
  FOR v_chapter IN
    SELECT c.id, c.chapter_name, c.subject, c.batch_id, b.exam_type, b.grade
    FROM chapters c
    JOIN batches b ON c.batch_id = b.id
    WHERE b.is_active = true
  LOOP
    -- Determine correct grade based on NCERT syllabus
    v_correct_grade := NULL;

    -- Physics mapping
    IF LOWER(v_chapter.subject) = 'physics' THEN
      IF LOWER(v_chapter.chapter_name) ~* '(units and measure|motion in a straight|motion in a plane|laws of motion|work.*(power|energy)|rotational|gravitation|mechanical properties|thermal properties|thermodynamics|kinetic theory|oscillation|waves|simple harmonic|physical world|fluid)' THEN
        v_correct_grade := 11;
      ELSIF LOWER(v_chapter.chapter_name) ~* '(electr|current electricity|magnet|electromagnetic|alternating|ray optic|wave optic|optic|dual nature|atoms|nucle|semiconductor|communication|capacitance)' THEN
        v_correct_grade := 12;
      END IF;
    END IF;

    -- Chemistry mapping
    IF LOWER(v_chapter.subject) = 'chemistry' THEN
      IF LOWER(v_chapter.chapter_name) ~* '(basic concepts|structure of atom|atomic structure|classification of elements|periodicity|chemical bonding|states of matter|thermodynamics|chemical thermodynamics|equilibrium|redox|hydrogen|s.block|p.block.*1[34]|organic.*basic|general organic|hydrocarbons|environmental chemistry)' THEN
        v_correct_grade := 11;
      ELSIF LOWER(v_chapter.chapter_name) ~* '(solid state|solutions|electrochemistry|chemical kinetics|surface chemistry|metallurgy|isolation of elements|p.block|d.and.f|d.block|transition|coordination|haloalkane|alcohol|phenol|ether|aldehyde|ketone|carboxylic|amine|nitrogen|biomolecule|polymer|chemistry in everyday|haloarene)' THEN
        v_correct_grade := 12;
      END IF;
    END IF;

    -- Mathematics mapping
    IF LOWER(v_chapter.subject) = 'mathematics' THEN
      IF LOWER(v_chapter.chapter_name) ~* '(^sets|trigonometric function|mathematical induction|complex number|quadratic|linear inequalit|permutation|combination|binomial|sequence|series|straight line|coordinate geometry|conic section|limits|derivatives$|mathematical reasoning|statistics|^probability$)' THEN
        v_correct_grade := 11;
      ELSIF LOWER(v_chapter.chapter_name) ~* '(inverse trigon|matri|determinant|continuity|differentiab|differentiation|application.*(deriv|integr)|integral|integration|area under|differential equation|vector|three dimensional|3d geometry|linear programming|probability.*(distrib|advanced)|circle|parabola|ellipse|hyperbola)' THEN
        v_correct_grade := 12;
      END IF;
    END IF;

    -- Biology mapping
    IF LOWER(v_chapter.subject) = 'biology' THEN
      IF LOWER(v_chapter.chapter_name) ~* '(living world|biological classification|plant kingdom|animal kingdom|morphology|anatomy.*plant|structural organisation|cell.*(unit|biology|structure)|biomolecule|cell.*(cycle|division)|transport in plant|mineral nutrition|photosynthesis|respiration in plant|plant growth|digestion|breathing|body fluid|circulation|excret|locomotion|neural|nervous|chemical coordination|endocrine)' THEN
        v_correct_grade := 11;
      ELSIF LOWER(v_chapter.chapter_name) ~* '(reproduction|sexual reproduction|human reproduction|reproductive health|inheritance|variation|genetics|molecular.*(basis|biology)|evolution|human health|disease|food production|microbes|biotechnology|organisms and population|ecology|ecosystem|biodiversity|environmental issue)' THEN
        v_correct_grade := 12;
      END IF;
    END IF;

    -- Skip if no mapping found or already correct
    IF v_correct_grade IS NULL OR v_chapter.grade = v_correct_grade THEN
      CONTINUE;
    END IF;

    -- Find target batch
    SELECT * INTO v_target_batch
    FROM batches
    WHERE exam_type = v_chapter.exam_type
      AND grade = v_correct_grade
      AND is_active = true
    LIMIT 1;

    IF v_target_batch IS NULL THEN
      CONTINUE;
    END IF;

    -- Find or create target chapter
    SELECT id INTO v_target_chapter_id
    FROM chapters
    WHERE LOWER(chapter_name) = LOWER(v_chapter.chapter_name)
      AND LOWER(subject) = LOWER(v_chapter.subject)
      AND batch_id = v_target_batch.id
    LIMIT 1;

    IF v_target_chapter_id IS NULL THEN
      INSERT INTO chapters (chapter_name, subject, batch_id, is_active)
      VALUES (v_chapter.chapter_name, v_chapter.subject, v_target_batch.id, true)
      RETURNING id INTO v_target_chapter_id;
    END IF;

    -- Move questions
    UPDATE questions
    SET batch_id = v_target_batch.id, chapter_id = v_target_chapter_id
    WHERE chapter_id = v_chapter.id;
    GET DIAGNOSTICS v_moved_count = ROW_COUNT;

    v_moved := v_moved + v_moved_count;

    v_moves := v_moves || jsonb_build_object(
      'chapter', v_chapter.chapter_name,
      'subject', v_chapter.subject,
      'from_grade', v_chapter.grade,
      'to_grade', v_correct_grade,
      'questions', v_moved_count
    );

    -- Deactivate empty source chapter
    IF v_moved_count > 0 THEN
      UPDATE chapters SET is_active = false
      WHERE id = v_chapter.id
        AND NOT EXISTS (SELECT 1 FROM questions WHERE chapter_id = v_chapter.id LIMIT 1);
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'success', true,
    'total_questions_moved', v_moved,
    'chapters_processed', jsonb_array_length(v_moves),
    'moves', v_moves
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.fix_mojibake(t text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  res text := '';
  pos int := 1;
  len int;
  ch  text;
  code int;
  run text;
  dec text;
  bytes bytea;
  b int;
  k int;
  ok boolean;
BEGIN
  IF t IS NULL THEN RETURN NULL; END IF;
  len := length(t);
  WHILE pos <= len LOOP
    ch := substr(t, pos, 1);
    code := ascii(ch);
    IF code >= 128 THEN
      run := '';
      WHILE pos <= len LOOP
        ch := substr(t, pos, 1);
        code := ascii(ch);
        EXIT WHEN code < 128;
        run := run || ch;
        pos := pos + 1;
      END LOOP;

      ok := true;
      bytes := ''::bytea;
      FOR k IN 1..length(run) LOOP
        b := public.mojibake_byte(substr(run, k, 1));
        IF b IS NULL THEN ok := false; EXIT; END IF;
        bytes := bytes || set_byte('\x00'::bytea, 0, b);
      END LOOP;

      dec := NULL;
      IF ok THEN
        BEGIN
          dec := convert_from(bytes, 'UTF8');
        EXCEPTION WHEN OTHERS THEN
          dec := NULL;
        END;
      END IF;
      res := res || COALESCE(dec, run);
    ELSE
      res := res || ch;
      pos := pos + 1;
    END IF;
  END LOOP;
  RETURN res;
END;
$function$

