CREATE OR REPLACE FUNCTION public.generate_referral_code()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  alphabet TEXT := 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
  candidate TEXT;
  raw TEXT;
  ch TEXT;
  i INT;
  attempt INT := 0;
BEGIN
  LOOP
    candidate := 'JN';
    raw := upper(md5(random()::text || clock_timestamp()::text));
    FOR i IN 1..length(raw) LOOP
      ch := substring(raw from i for 1);
      IF position(ch in alphabet) > 0 THEN
        candidate := candidate || ch;
        EXIT WHEN length(candidate) >= 8;
      END IF;
    END LOOP;
    -- pad if too short
    WHILE length(candidate) < 8 LOOP
      candidate := candidate || substring(alphabet from (floor(random() * length(alphabet))::int + 1) for 1);
    END LOOP;
    candidate := substring(candidate from 1 for 8);
    EXIT WHEN NOT EXISTS (SELECT 1 FROM public.profiles WHERE referral_code = candidate);
    attempt := attempt + 1;
    EXIT WHEN attempt > 12;
  END LOOP;
  RETURN candidate;
END;
$function$

CREATE OR REPLACE FUNCTION public.get_contract_status()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_today date := (now() AT TIME ZONE 'Asia/Kolkata')::date;
  c public.user_contracts%ROWTYPE;
  v_attempted int := 0;
  v_correct int := 0;
  v_span int;
  v_elapsed int;
BEGIN
  IF v_uid IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'unauthenticated'); END IF;

  SELECT * INTO c FROM public.user_contracts
  WHERE user_id = v_uid AND status = 'active' AND ends_on >= v_today
  ORDER BY created_at DESC LIMIT 1;

  IF c.id IS NULL THEN RETURN jsonb_build_object('ok', true, 'contract', NULL); END IF;

  SELECT count(*), count(*) FILTER (WHERE is_correct)
  INTO v_attempted, v_correct
  FROM public.question_attempts
  WHERE user_id = v_uid
    AND COALESCE(mode, 'practice') <> 'test'
    AND (attempted_at AT TIME ZONE 'Asia/Kolkata')::date BETWEEN c.starts_on AND c.ends_on;

  v_span := GREATEST(1, (c.ends_on - c.starts_on));
  v_elapsed := GREATEST(1, LEAST(v_span, (v_today - c.starts_on) + 1));

  RETURN jsonb_build_object('ok', true, 'contract', jsonb_build_object(
    'id', c.id,
    'target_questions', c.target_questions,
    'target_accuracy', c.target_accuracy,
    'reward_points', c.reward_points,
    'starts_on', c.starts_on,
    'ends_on', c.ends_on,
    'status', c.status,
    'attempted', v_attempted,
    'accuracy', CASE WHEN v_attempted > 0 THEN round((v_correct::numeric / v_attempted) * 100) ELSE 0 END,
    'expected_by_now', ceil(c.target_questions::numeric * v_elapsed / v_span)::int,
    'days_left', GREATEST(0, c.ends_on - v_today)
  ));
END;
$function$

CREATE OR REPLACE FUNCTION public.get_system_health_status()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    error_count int;
begin
    select count(*) into error_count from public.system_logs where level in ('error', 'critical') and created_at > now() - interval '24 hours';

    return jsonb_build_object(
        'status', case when error_count > 50 then 'degraded' else 'healthy' end,
        'recent_errors_24h', error_count,
        'timestamp', now()
    );
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_referral_update()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF has_role(auth.uid(), 'admin'::app_role) OR has_role(auth.uid(), 'super_admin'::app_role) THEN
    RETURN NEW;
  END IF;
  IF NEW.reward_granted IS DISTINCT FROM OLD.reward_granted
     OR NEW.status IS DISTINCT FROM OLD.status
     OR NEW.referrer_id IS DISTINCT FROM OLD.referrer_id
     OR NEW.referred_id IS DISTINCT FROM OLD.referred_id THEN
    RAISE EXCEPTION 'Cannot modify protected referral fields';
  END IF;
  RETURN NEW;
END;
$function$

