CREATE OR REPLACE FUNCTION public.join_current_league()
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_start date := public.current_cycle_start();
  v_end date := v_start + 6;
  v_tier text := 'bronze';
  v_league uuid;
BEGIN
  IF v_uid IS NULL THEN RETURN NULL; END IF;

  SELECT lm.league_id INTO v_league
  FROM public.league_members lm
  JOIN public.leagues l ON l.id = lm.league_id
  WHERE lm.user_id = v_uid AND l.cycle_start = v_start
  LIMIT 1;
  IF v_league IS NOT NULL THEN RETURN v_league; END IF;

  SELECT COALESCE(lm.next_tier, l.tier) INTO v_tier
  FROM public.league_members lm
  JOIN public.leagues l ON l.id = lm.league_id
  WHERE lm.user_id = v_uid
  ORDER BY l.cycle_start DESC LIMIT 1;
  v_tier := COALESCE(v_tier, 'bronze');

  SELECT l.id INTO v_league
  FROM public.leagues l
  WHERE l.cycle_start = v_start AND l.tier = v_tier
    AND (SELECT count(*) FROM public.league_members m WHERE m.league_id = l.id) < 30
  ORDER BY l.created_at
  LIMIT 1;

  IF v_league IS NULL THEN
    INSERT INTO public.leagues (tier, cycle_start, cycle_end)
    VALUES (v_tier, v_start, v_end)
    RETURNING id INTO v_league;
  END IF;

  INSERT INTO public.league_members (league_id, user_id)
  VALUES (v_league, v_uid)
  ON CONFLICT (league_id, user_id) DO NOTHING;

  RETURN v_league;
END;
$function$

CREATE OR REPLACE FUNCTION public.log_points(p_user_id uuid, p_action_type text, p_points integer, p_description text DEFAULT NULL::text, p_reference_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_id uuid;
  v_allowed_actions text[] := ARRAY[
    'correct_answer', 'streak_bonus', 'daily_goal', 'badge_earned',
    'referral_reward', 'first_login', 'topic_mastery', 'test_completion'
  ];
  v_max_points integer := 100; -- Max points per single action
BEGIN
  -- Only allow logging for the authenticated user
  IF auth.uid() IS NULL OR auth.uid() != p_user_id THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;

  -- Validate action type
  IF NOT (p_action_type = ANY(v_allowed_actions)) THEN
    RAISE EXCEPTION 'Invalid action type: %', p_action_type;
  END IF;

  -- Cap points to prevent inflation
  IF p_points > v_max_points OR p_points < 0 THEN
    RAISE EXCEPTION 'Points must be between 0 and %', v_max_points;
  END IF;

  INSERT INTO points_log (user_id, action_type, points, description, reference_id)
  VALUES (p_user_id, p_action_type, p_points, p_description, p_reference_id)
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.log_points(p_user_id uuid, p_points integer, p_action_type text, p_description text DEFAULT NULL::text, p_reference_id text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_id uuid;
BEGIN
  INSERT INTO public.points_log (user_id, points, action_type, description, reference_id)
  VALUES (p_user_id, p_points, p_action_type, p_description, p_reference_id) RETURNING id INTO v_id;
  UPDATE public.profiles SET total_points = COALESCE(total_points,0) + p_points, updated_at = now() WHERE id = p_user_id;
  RETURN v_id;
END $function$

CREATE OR REPLACE FUNCTION public.protect_premium_fields()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  -- Allow SECURITY DEFINER functions (which run as the function owner) to pass through
  IF current_user IN ('postgres', 'supabase_admin') THEN
    RETURN NEW;
  END IF;

  -- If the caller is NOT an admin, block changes to sensitive fields
  IF NOT (has_role(auth.uid(), 'admin'::app_role) OR has_role(auth.uid(), 'super_admin'::app_role)) THEN
    NEW.is_premium := OLD.is_premium;
    NEW.subscription_end_date := OLD.subscription_end_date;
    NEW.daily_question_limit := OLD.daily_question_limit;
    NEW.total_points := OLD.total_points;
    NEW.current_streak := OLD.current_streak;
    NEW.longest_streak := OLD.longest_streak;
    NEW.questions_completed := OLD.questions_completed;
    NEW.total_questions_solved := OLD.total_questions_solved;
    NEW.overall_accuracy := OLD.overall_accuracy;
    NEW.level := OLD.level;
    NEW.level_progress := OLD.level_progress;
    NEW.referral_code := OLD.referral_code;
    NEW.goal_locked := OLD.goal_locked;
    NEW.goal_locked_at := OLD.goal_locked_at;
    -- Lock grade and target_exam once set (goal_locked = true)
    IF OLD.goal_locked = true THEN
      NEW.grade := OLD.grade;
      NEW.target_exam := OLD.target_exam;
    END IF;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.questions_legacy_backfill()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_chapter RECORD;
  v_topic_id uuid;
  v_correct_letter text;
  v_correct_index int;
  v_diff difficulty_level;
BEGIN
  -- question_text from question
  IF NEW.question_text IS NULL AND NEW.question IS NOT NULL THEN
    NEW.question_text := NEW.question;
  ELSIF NEW.question IS NULL AND NEW.question_text IS NOT NULL THEN
    NEW.question := NEW.question_text;
  END IF;

  -- options jsonb from option_a..d
  IF NEW.options IS NULL AND NEW.option_a IS NOT NULL THEN
    NEW.options := jsonb_build_array(
      jsonb_build_object('label', 'A', 'text', NEW.option_a),
      jsonb_build_object('label', 'B', 'text', COALESCE(NEW.option_b, '')),
      jsonb_build_object('label', 'C', 'text', COALESCE(NEW.option_c, '')),
      jsonb_build_object('label', 'D', 'text', COALESCE(NEW.option_d, ''))
    );
  END IF;

  -- correct_options from correct_option letter
  IF (NEW.correct_options IS NULL OR array_length(NEW.correct_options, 1) IS NULL) 
     AND NEW.correct_option IS NOT NULL THEN
    v_correct_letter := upper(trim(NEW.correct_option));
    -- Strip OPTION_ prefix if present
    v_correct_letter := regexp_replace(v_correct_letter, '^OPTION_', '');
    IF v_correct_letter IN ('A', 'B', 'C', 'D') THEN
      NEW.correct_options := ARRAY[v_correct_letter];
    END IF;
  END IF;

  -- exam_relevance from exam text
  IF NEW.exam_relevance IS NULL OR array_length(NEW.exam_relevance, 1) IS NULL THEN
    IF upper(COALESCE(NEW.exam, '')) = 'NEET' THEN
      NEW.exam_relevance := ARRAY['NEET']::exam_code[];
    ELSIF upper(COALESCE(NEW.exam, '')) IN ('JEE', 'JEE_MAINS', 'JEE-MAINS') THEN
      NEW.exam_relevance := ARRAY['JEE_MAINS']::exam_code[];
    ELSIF upper(COALESCE(NEW.exam, '')) IN ('JEE_ADVANCED', 'JEE-ADVANCED') THEN
      NEW.exam_relevance := ARRAY['JEE_ADVANCED']::exam_code[];
    ELSE
      NEW.exam_relevance := ARRAY['JEE_MAINS']::exam_code[];
    END IF;
  END IF;

  -- pyq_year from year
  IF NEW.pyq_year IS NULL AND NEW.year IS NOT NULL THEN
    NEW.pyq_year := NEW.year;
    NEW.is_pyq := true;
  END IF;

  -- Resolve chapter row (gives us subject_id too)
  IF NEW.chapter_id IS NOT NULL THEN
    SELECT id, subject_id, subject, name INTO v_chapter
    FROM public.chapters WHERE id = NEW.chapter_id;

    IF FOUND THEN
      IF NEW.subject_id IS NULL THEN NEW.subject_id := v_chapter.subject_id; END IF;
      IF NEW.subject IS NULL THEN NEW.subject := v_chapter.subject; END IF;
      IF NEW.chapter IS NULL THEN NEW.chapter := v_chapter.name; END IF;
    END IF;
  END IF;

  -- Resolve subject_id from subject text if still missing
  IF NEW.subject_id IS NULL AND NEW.subject IS NOT NULL THEN
    SELECT id INTO NEW.subject_id
    FROM public.subjects WHERE LOWER(name) = LOWER(NEW.subject) LIMIT 1;
  END IF;

  -- Ensure topic_id: pick first topic of chapter, or create one
  IF NEW.topic_id IS NULL AND NEW.chapter_id IS NOT NULL THEN
    SELECT id INTO v_topic_id
    FROM public.topics WHERE chapter_id = NEW.chapter_id ORDER BY display_order LIMIT 1;

    IF v_topic_id IS NULL THEN
      INSERT INTO public.topics (chapter_id, name, slug, display_order, is_active)
      VALUES (NEW.chapter_id, 'General', 'general-' || substr(NEW.chapter_id::text, 1, 8), 0, true)
      RETURNING id INTO v_topic_id;
    END IF;
    NEW.topic_id := v_topic_id;
  END IF;

  -- Difficulty mapping
  IF NEW.difficulty_jee_mains IS NULL AND NEW.difficulty IS NOT NULL THEN
    v_diff := CASE upper(NEW.difficulty)
      WHEN 'EASY' THEN 'EASY'::difficulty_level
      WHEN 'HARD' THEN 'HARD'::difficulty_level
      ELSE 'MEDIUM'::difficulty_level
    END;
    NEW.difficulty_jee_mains := v_diff;
    NEW.difficulty_neet := v_diff;
  END IF;

  RETURN NEW;
END;
$function$

