CREATE OR REPLACE FUNCTION public.recalc_user_accuracy()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  target_user_id uuid;
  v_total bigint;
  v_correct bigint;
  v_accuracy numeric;
BEGIN
  target_user_id := COALESCE(NEW.user_id, OLD.user_id);
  IF target_user_id IS NULL THEN RETURN NULL; END IF;

  SELECT COUNT(*), COUNT(*) FILTER (WHERE is_correct = true)
  INTO v_total, v_correct
  FROM public.question_attempts
  WHERE user_id = target_user_id
    AND mode = 'practice'
    AND is_correct IS NOT NULL;

  IF v_total = 0 THEN
    v_accuracy := 0;
  ELSE
    v_accuracy := ROUND((v_correct::numeric / v_total::numeric) * 100, 2);
  END IF;

  UPDATE public.profiles
  SET overall_accuracy = v_accuracy,
      total_questions_solved = v_total,
      updated_at = now()
  WHERE id = target_user_id;

  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.redeem_referral(_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  referrer_uid UUID;
  me UUID := auth.uid();
  my_created TIMESTAMPTZ;
  existing_row RECORD;
BEGIN
  IF me IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'unauthenticated');
  END IF;

  IF _code IS NULL OR length(trim(_code)) < 4 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_code');
  END IF;

  SELECT id INTO referrer_uid
    FROM public.profiles WHERE referral_code = upper(trim(_code)) LIMIT 1;

  IF referrer_uid IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'code_not_found');
  END IF;

  IF referrer_uid = me THEN
    RETURN jsonb_build_object('ok', false, 'error', 'cannot_refer_self');
  END IF;

  SELECT created_at INTO my_created FROM public.profiles WHERE id = me;
  IF my_created IS NOT NULL AND my_created < now() - interval '30 days' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'redemption_window_expired');
  END IF;

  SELECT * INTO existing_row FROM public.referrals
    WHERE referred_user_id = me OR referred_id = me LIMIT 1;
  IF existing_row.id IS NOT NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'already_referred');
  END IF;

  INSERT INTO public.referrals (referrer_id, referred_user_id, referred_id, referral_code, status, reward_granted)
  VALUES (referrer_uid, me, me, upper(trim(_code)), 'pending', false);

  RETURN jsonb_build_object('ok', true, 'referrer_id', referrer_uid);
END;
$function$

CREATE OR REPLACE FUNCTION public.repair_streak()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_today date := (now() AT TIME ZONE 'Asia/Kolkata')::date;
  v_start timestamptz := (date_trunc('day', now() AT TIME ZONE 'Asia/Kolkata') AT TIME ZONE 'Asia/Kolkata');
  v_count bigint;
  v_p RECORD;
BEGIN
  IF v_uid IS NULL THEN RETURN jsonb_build_object('error','Unauthorized'); END IF;

  SELECT COALESCE(pending_streak_repair,0) AS repair, pending_streak_repair_date
  INTO v_p FROM public.profiles WHERE id = v_uid;

  IF v_p.repair <= 0 OR v_p.pending_streak_repair_date IS DISTINCT FROM v_today THEN
    RETURN jsonb_build_object('success', false, 'reason', 'no_repair_available');
  END IF;

  SELECT count(*) INTO v_count
  FROM public.question_attempts
  WHERE user_id = v_uid AND COALESCE(mode,'practice') <> 'test' AND created_at >= v_start;

  IF v_count < 10 THEN
    RETURN jsonb_build_object('success', false, 'reason', 'not_enough', 'solved', v_count, 'needed', 10);
  END IF;

  UPDATE public.profiles
  SET current_streak = v_p.repair,
      longest_streak = GREATEST(COALESCE(longest_streak,0), v_p.repair),
      last_streak_date = v_today,
      pending_streak_repair = 0,
      pending_streak_repair_date = NULL,
      updated_at = now()
  WHERE id = v_uid;

  RETURN jsonb_build_object('success', true, 'streak', v_p.repair);
END;
$function$

CREATE OR REPLACE FUNCTION public.reset_user_progress(p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_qa INT := 0;
  v_ta INT := 0;
  v_pl INT := 0;
BEGIN
  DELETE FROM public.question_attempts WHERE user_id = p_user_id;
  GET DIAGNOSTICS v_qa = ROW_COUNT;
  DELETE FROM public.test_attempts WHERE user_id = p_user_id;
  GET DIAGNOSTICS v_ta = ROW_COUNT;
  DELETE FROM public.test_sessions WHERE user_id = p_user_id;
  DELETE FROM public.points_log WHERE user_id = p_user_id;
  GET DIAGNOSTICS v_pl = ROW_COUNT;
  DELETE FROM public.topic_mastery WHERE user_id = p_user_id;
  DELETE FROM public.user_content_access WHERE user_id = p_user_id;

  UPDATE public.profiles SET
    questions_completed = 0,
    total_questions_solved = 0,
    overall_accuracy = 0,
    total_points = 0,
    current_streak = 0,
    level = 'BEGINNER',
    level_progress = 0,
    last_activity = now(),
    updated_at = now()
  WHERE id = p_user_id;

  RETURN jsonb_build_object('question_attempts', v_qa, 'test_attempts', v_ta, 'points_log', v_pl, 'profile_reset', true);
END;
$function$

CREATE OR REPLACE FUNCTION public.rls_auto_enable()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$function$

