CREATE OR REPLACE FUNCTION public.update_revision_from_attempt()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  q_chapter UUID;
  q_topic UUID;
  q_subject TEXT;
  new_interval NUMERIC;
  new_ease NUMERIC;
  new_streak INT;
  existing public.revision_schedule%ROWTYPE;
BEGIN
  SELECT chapter_id, topic_id, subject INTO q_chapter, q_topic, q_subject
  FROM public.questions WHERE id = NEW.question_id;

  IF q_chapter IS NULL AND q_topic IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT * INTO existing FROM public.revision_schedule
   WHERE user_id = NEW.user_id
     AND COALESCE(topic_id, '00000000-0000-0000-0000-000000000000'::uuid) = COALESCE(q_topic, '00000000-0000-0000-0000-000000000000'::uuid)
     AND COALESCE(chapter_id, '00000000-0000-0000-0000-000000000000'::uuid) = COALESCE(q_chapter, '00000000-0000-0000-0000-000000000000'::uuid)
   LIMIT 1;

  IF NEW.is_correct THEN
    new_streak := COALESCE(existing.correct_streak, 0) + 1;
    new_ease := LEAST(2.8, COALESCE(existing.ease_factor, 2.5) + 0.05);
    new_interval := CASE
      WHEN new_streak = 1 THEN 1
      WHEN new_streak = 2 THEN 3
      WHEN new_streak = 3 THEN 7
      ELSE LEAST(60, COALESCE(existing.interval_days, 1) * new_ease)
    END;
  ELSE
    new_streak := 0;
    new_ease := GREATEST(1.5, COALESCE(existing.ease_factor, 2.5) - 0.2);
    new_interval := 1;
  END IF;

  INSERT INTO public.revision_schedule (
    user_id, subject, chapter_id, topic_id,
    next_due_at, interval_days, ease_factor,
    last_reviewed_at, reviews_count, correct_streak, last_accuracy, updated_at
  ) VALUES (
    NEW.user_id, q_subject, q_chapter, q_topic,
    now() + (new_interval || ' days')::interval, new_interval, new_ease,
    now(), 1, new_streak, CASE WHEN NEW.is_correct THEN 1 ELSE 0 END, now()
  )
  ON CONFLICT (user_id, COALESCE(topic_id, '00000000-0000-0000-0000-000000000000'::uuid), COALESCE(chapter_id, '00000000-0000-0000-0000-000000000000'::uuid))
  DO UPDATE SET
    next_due_at = now() + (new_interval || ' days')::interval,
    interval_days = new_interval,
    ease_factor = new_ease,
    last_reviewed_at = now(),
    reviews_count = revision_schedule.reviews_count + 1,
    correct_streak = new_streak,
    last_accuracy = 0.7 * COALESCE(revision_schedule.last_accuracy, 0.5) + 0.3 * (CASE WHEN NEW.is_correct THEN 1 ELSE 0 END),
    subject = COALESCE(q_subject, revision_schedule.subject),
    updated_at = now();

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.update_streak_stats(p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_profile record;
  v_today text;
  v_yesterday text;
  v_today_start timestamptz;
  v_tomorrow_start timestamptz;
  v_new_streak integer;
  v_new_longest integer;
  v_days_since integer;
  v_used_freeze boolean := false;
  v_today_count bigint;
  v_daily_goal integer;
  v_reference_date date;
begin
  if auth.uid() is null or auth.uid() != p_user_id then
    return jsonb_build_object('error', 'Unauthorized');
  end if;

  v_today := to_char(now() at time zone 'Asia/Kolkata', 'YYYY-MM-DD');
  v_yesterday := to_char((now() at time zone 'Asia/Kolkata' - interval '1 day'), 'YYYY-MM-DD');

  v_today_start := (date_trunc('day', now() at time zone 'Asia/Kolkata') at time zone 'Asia/Kolkata');
  v_tomorrow_start := v_today_start + interval '1 day';

  select current_streak, longest_streak, last_activity_date, streak_freeze_available, daily_goal, last_streak_date
  into v_profile
  from profiles where id = p_user_id;

  if not found then
    return jsonb_build_object('error', 'Profile not found');
  end if;

  v_daily_goal := coalesce(v_profile.daily_goal, 15);

  -- IMPORTANT: capture reference date BEFORE we overwrite last_activity_date
  v_reference_date := coalesce(v_profile.last_streak_date, v_profile.last_activity_date);

  select count(*) into v_today_count
  from question_attempts
  where user_id = p_user_id
    and mode = 'practice'
    and created_at >= v_today_start
    and created_at < v_tomorrow_start;

  -- Always update activity timestamp
  update profiles set
    last_activity_date = v_today::date,
    last_activity = now(),
    updated_at = now()
  where id = p_user_id;

  -- Daily goal not met yet -> no streak change
  if v_today_count < v_daily_goal then
    return jsonb_build_object(
      'success', true,
      'streak', coalesce(v_profile.current_streak, 0),
      'daily_goal_met', false,
      'today_count', v_today_count,
      'daily_goal', v_daily_goal
    );
  end if;

  -- Already credited streak for today -> idempotent
  if v_profile.last_streak_date = v_today::date then
    v_new_streak := greatest(coalesce(v_profile.current_streak, 0), 1);
    v_new_longest := greatest(v_new_streak, coalesce(v_profile.longest_streak, 0));

    update profiles set
      current_streak = v_new_streak,
      longest_streak = v_new_longest,
      last_streak_date = v_today::date,
      updated_at = now()
    where id = p_user_id;

    return jsonb_build_object(
      'success', true,
      'streak', v_new_streak,
      'longest_streak', v_new_longest,
      'daily_goal_met', true,
      'already_updated', true
    );
  end if;

  -- New streak day: decide based on reference date (last_streak_date preferred)
  v_new_streak := coalesce(v_profile.current_streak, 0);

  if v_reference_date = v_yesterday::date then
    -- Continued from yesterday -> increment
    v_new_streak := greatest(1, v_new_streak + 1);
  elsif v_reference_date is not null then
    v_days_since := (v_today::date - v_reference_date)::integer;
    if v_days_since = 2 and coalesce(v_profile.streak_freeze_available, false) then
      v_new_streak := greatest(1, v_new_streak + 1);
      v_used_freeze := true;
    else
      -- Gap > 1 day, no freeze -> restart at 1
      v_new_streak := 1;
    end if;
  else
    -- First ever streak
    v_new_streak := 1;
  end if;

  v_new_longest := greatest(v_new_streak, coalesce(v_profile.longest_streak, 0));

  update profiles set
    current_streak = v_new_streak,
    longest_streak = v_new_longest,
    last_streak_date = v_today::date,
    streak_freeze_available = case when v_used_freeze then false else streak_freeze_available end,
    updated_at = now()
  where id = p_user_id;

  return jsonb_build_object(
    'success', true,
    'streak', v_new_streak,
    'longest_streak', v_new_longest,
    'daily_goal_met', true,
    'used_freeze', v_used_freeze
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.validate_practice_answer(p_question_id uuid, p_selected_options text[] DEFAULT NULL::text[], p_numerical_answer numeric DEFAULT NULL::numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  q public.questions%ROWTYPE;
  v_selected text[];
  v_correct text[];
  v_is_correct boolean := false;
BEGIN
  SELECT * INTO q
  FROM public.questions
  WHERE id = p_question_id
    AND COALESCE(is_active, true) = true;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('error', 'question_not_found', 'is_correct', false);
  END IF;

  IF q.question_type IN ('numerical_int', 'numerical_decimal') OR q.numerical_answer IS NOT NULL THEN
    v_is_correct := p_numerical_answer IS NOT NULL
      AND q.numerical_answer IS NOT NULL
      AND ABS(p_numerical_answer - q.numerical_answer) <= COALESCE(q.numerical_tolerance, 0);
  ELSE
    SELECT array_agg(upper(trim(x)) ORDER BY upper(trim(x))) INTO v_selected
    FROM unnest(COALESCE(p_selected_options, ARRAY[]::text[])) AS x
    WHERE trim(x) <> '';

    SELECT array_agg(upper(trim(x)) ORDER BY upper(trim(x))) INTO v_correct
    FROM unnest(
      CASE
        WHEN q.correct_options IS NOT NULL AND array_length(q.correct_options, 1) > 0 THEN q.correct_options
        WHEN q.correct_option IS NOT NULL AND trim(q.correct_option) <> '' THEN string_to_array(q.correct_option, ',')
        ELSE ARRAY[]::text[]
      END
    ) AS x
    WHERE trim(x) <> '';

    v_is_correct := COALESCE(array_length(v_selected, 1), 0) > 0
      AND COALESCE(array_length(v_correct, 1), 0) > 0
      AND v_selected = v_correct;
  END IF;

  RETURN jsonb_build_object(
    'is_correct', COALESCE(v_is_correct, false),
    'correct_options', COALESCE(v_correct, q.correct_options),
    'correct_option', COALESCE(array_to_string(v_correct, ','), q.correct_option),
    'numerical_answer', q.numerical_answer,
    'explanation', COALESCE(q.explanation, '')
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_promo_code(p_code text, p_plan_id text, p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_code public.promo_codes%ROWTYPE; v_plan public.subscription_plans%ROWTYPE;
  v_user_uses int; v_discount numeric; v_final numeric;
BEGIN
  SELECT * INTO v_plan FROM public.subscription_plans WHERE id = p_plan_id AND is_active = true;
  IF NOT FOUND THEN RETURN jsonb_build_object('valid', false, 'reason','Plan not found'); END IF;
  SELECT * INTO v_code FROM public.promo_codes WHERE code = upper(trim(p_code));
  IF NOT FOUND THEN RETURN jsonb_build_object('valid', false, 'reason','Invalid promo code'); END IF;
  IF NOT v_code.is_active THEN RETURN jsonb_build_object('valid', false, 'reason','This code is no longer active'); END IF;
  IF v_code.starts_at IS NOT NULL AND v_code.starts_at > now() THEN RETURN jsonb_build_object('valid', false, 'reason','Not active yet'); END IF;
  IF v_code.expires_at IS NOT NULL AND v_code.expires_at < now() THEN RETURN jsonb_build_object('valid', false, 'reason','Expired'); END IF;
  IF v_code.max_redemptions IS NOT NULL AND v_code.current_redemptions >= v_code.max_redemptions THEN RETURN jsonb_build_object('valid', false, 'reason','Fully redeemed'); END IF;
  IF array_length(v_code.applicable_plan_ids,1) > 0 AND NOT (p_plan_id = ANY(v_code.applicable_plan_ids)) THEN RETURN jsonb_build_object('valid', false, 'reason','Not valid for selected plan'); END IF;
  IF v_code.min_amount > 0 AND v_plan.price < v_code.min_amount THEN RETURN jsonb_build_object('valid', false, 'reason','Plan price below minimum'); END IF;
  SELECT COUNT(*) INTO v_user_uses FROM public.promo_redemptions WHERE promo_code_id = v_code.id AND user_id = p_user_id;
  IF v_user_uses >= v_code.max_per_user THEN RETURN jsonb_build_object('valid', false, 'reason','Already used'); END IF;
  IF v_code.discount_type = 'percent' THEN v_discount := ROUND(v_plan.price * v_code.discount_value / 100);
  ELSE v_discount := LEAST(v_code.discount_value, v_plan.price); END IF;
  v_final := GREATEST(v_plan.price - v_discount, 1);
  RETURN jsonb_build_object('valid', true, 'promo_code_id', v_code.id, 'code', v_code.code,
    'discount_type', v_code.discount_type, 'discount_value', v_code.discount_value,
    'discount_applied', v_discount, 'original_price', v_plan.price, 'final_price', v_final);
END $function$

CREATE OR REPLACE FUNCTION public.validate_question_answer(p_question_id uuid, p_selected_options text[] DEFAULT NULL::text[], p_numerical_answer numeric DEFAULT NULL::numeric, p_exam exam_code DEFAULT NULL::exam_code)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  q public.questions%ROWTYPE;
  v_is_correct boolean := false;
BEGIN
  SELECT * INTO q FROM public.questions WHERE id = p_question_id AND is_active = true;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('error', 'question_not_found');
  END IF;

  IF q.question_type IN ('numerical_int','numerical_decimal') THEN
    v_is_correct := p_numerical_answer IS NOT NULL
                    AND ABS(p_numerical_answer - q.numerical_answer) <= COALESCE(q.numerical_tolerance, 0);
  ELSE
    v_is_correct := p_selected_options IS NOT NULL
      AND (SELECT array_agg(x ORDER BY x) FROM unnest(p_selected_options) x)
        = (SELECT array_agg(x ORDER BY x) FROM unnest(q.correct_options) x);
  END IF;

  RETURN jsonb_build_object(
    'is_correct', v_is_correct,
    'correct_options', q.correct_options,
    'numerical_answer', q.numerical_answer,
    'explanation', q.explanation,
    'marking', jsonb_build_object(
      'correct', q.marking_correct,
      'incorrect', q.marking_incorrect,
      'unattempted', q.marking_unattempted
    )
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_question_answer(p_question_id uuid, p_selected_option text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE q public.questions%ROWTYPE; v_is_correct boolean := false; v_correct text;
BEGIN
  SELECT * INTO q FROM public.questions WHERE id = p_question_id AND is_active = true;
  IF NOT FOUND THEN RETURN jsonb_build_object('error','question_not_found'); END IF;
  IF q.correct_options IS NOT NULL AND array_length(q.correct_options,1) >= 1 THEN v_correct := q.correct_options[1];
  ELSE v_correct := q.correct_option; END IF;
  v_is_correct := p_selected_option IS NOT NULL AND v_correct IS NOT NULL AND upper(p_selected_option) = upper(v_correct);
  RETURN jsonb_build_object('is_correct', v_is_correct, 'correct_option', v_correct, 'explanation', COALESCE(q.explanation,''));
END $function$

CREATE OR REPLACE FUNCTION public.validate_question_hierarchy()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_topic_chapter uuid;
  v_chapter_subject uuid;
  v_concept_topic uuid;
BEGIN
  SELECT chapter_id INTO v_topic_chapter FROM public.topics WHERE id = NEW.topic_id;
  IF v_topic_chapter IS DISTINCT FROM NEW.chapter_id THEN
    RAISE EXCEPTION 'Topic % does not belong to chapter %', NEW.topic_id, NEW.chapter_id;
  END IF;
  SELECT subject_id INTO v_chapter_subject FROM public.chapters WHERE id = NEW.chapter_id;
  IF v_chapter_subject IS DISTINCT FROM NEW.subject_id THEN
    RAISE EXCEPTION 'Chapter % does not belong to subject %', NEW.chapter_id, NEW.subject_id;
  END IF;
  IF NEW.concept_id IS NOT NULL THEN
    SELECT topic_id INTO v_concept_topic FROM public.concepts WHERE id = NEW.concept_id;
    IF v_concept_topic IS DISTINCT FROM NEW.topic_id THEN
      RAISE EXCEPTION 'Concept % does not belong to topic %', NEW.concept_id, NEW.topic_id;
    END IF;
  END IF;
  RETURN NEW;
END;
$function$
